package io.github.ephym6.plantid.data.plant

import io.github.ephym6.plantid.domain.plant.CareData
import io.github.ephym6.plantid.domain.plant.ContentSource
import io.github.ephym6.plantid.domain.plant.Plant
import io.github.ephym6.plantid.domain.plant.PlantCatalog
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Parses `assets/plants.json` (generated by `Mobile-App/tools/sync_plant_data.py`).
 * Pure Kotlin, so it is unit-tested against the real bundled file.
 */
internal object PlantDataParser {

    const val SUPPORTED_SCHEMA_VERSION = 1

    private val json = Json { ignoreUnknownKeys = true }

    /** @throws IllegalArgumentException if the file is malformed or has an unsupported schema. */
    fun parse(text: String): PlantCatalog {
        val file = try {
            json.decodeFromString<PlantDataFile>(text)
        } catch (e: kotlinx.serialization.SerializationException) {
            throw IllegalArgumentException("plants.json is malformed", e)
        }
        require(file.schemaVersion == SUPPORTED_SCHEMA_VERSION) {
            "plants.json schema ${file.schemaVersion} is not supported (expected $SUPPORTED_SCHEMA_VERSION)"
        }
        val ids = file.plants.map { it.id }
        require(ids.size == ids.toSet().size) { "plants.json has duplicate plant ids" }
        return PlantCatalog(
            source = ContentSource(file.source.name, file.source.url, file.source.license),
            plants = file.plants.map { it.toPlant() },
        )
    }

    private fun PlantDto.toPlant() = Plant(
        id = id,
        classLabel = classLabel,
        commonName = commonName,
        scientificName = scientificName,
        family = family,
        care = care?.let {
            CareData(
                lightLux = it.lightLux?.toRange(),
                temperatureCelsius = it.temperatureCelsius?.toRange(),
                humidityPercent = it.humidityPercent,
                wateringIntervalDays = it.wateringIntervalDays,
            )
        },
    )

    private fun RangeDto.toRange() = min..max

    @Serializable
    private data class PlantDataFile(
        val schemaVersion: Int,
        val source: SourceDto,
        val plants: List<PlantDto>,
    )

    @Serializable
    private data class SourceDto(val name: String, val url: String? = null, val license: String? = null)

    @Serializable
    private data class PlantDto(
        val id: String,
        val classLabel: String,
        val commonName: String? = null,
        val scientificName: String? = null,
        val family: String? = null,
        val care: CareDto? = null,
    )

    @Serializable
    private data class CareDto(
        val lightLux: RangeDto? = null,
        val temperatureCelsius: RangeDto? = null,
        val humidityPercent: Int? = null,
        val wateringIntervalDays: Int? = null,
    )

    @Serializable
    private data class RangeDto(val min: Int, val max: Int)
}
